    "exp_desc": "தொழில்நுட்பம் சுகாதாரப் பராமரிப்பை மேலும் கருணையுள்ளதாக மாற்ற வேண்டும். சுவஸ்த்ய சேது நோயாளிகள் தங்கள் தாய்மொழியில் பேச உதவுகிறது.",
    "exp_b1": "சரிபார்க்கப்பட்ட சான்றுகளுடன் வெளிப்படையான மருத்துவர் சுயவிவரங்கள்",
