    "Consult Doctor": "ଡାକ୍ତରଙ୍କ ସହ ପରାମର୍ଶ କରନ୍ତୁ",
    "No health assessment recorded on this device yet.": "ଏହି ଡିଭାଇସରେ ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ସ୍ୱାସ୍ଥ୍ୟ ମୂଲ୍ୟାଙ୍କନ ରେକର୍ଡ ହୋଇନାହିଁ।",
    "Take Preliminary Assessment": "ପ୍ରାରମ୍ଭିକ ମୂଲ୍ୟାଙ୍କନ କରନ୍ତୁ",
    "Valued Patient": "ପ୍ରିୟ ରୋଗୀ",
